function h(v=''){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function level(id){return levels.find(x=>x.id===id)||levels[0]}async function readApiResponse(r,context='la API'){
  const contentType=r.headers.get('content-type')||'';
  const raw=await r.text();
  let d;
  if(!contentType.toLowerCase().includes('application/json')){
    const detail=raw.trim().slice(0,180).replace(/\\s+/g,' ');
    const routeHint=r.status===404
      ? 'La ruta no existe en el servidor desplegado.'
      : 'El servidor respondió con una página o texto en vez de JSON.';
    throw Error(`${context}: respuesta no válida (HTTP ${r.status}). ${routeHint}${detail?` Respuesta: ${detail}`:''}`);
  }
  try{d=JSON.parse(raw)}catch{
    throw Error(`${context}: el servidor indicó JSON, pero devolvió contenido inválido (HTTP ${r.status}).`);
  }
  if(!r.ok)throw Error(d.error||d.message||`${context}: error HTTP ${r.status}.`);
  return d;
}
function api(path,body){
  const url=path.includes('?')?`${path}&token=${encodeURIComponent(token)}`:`${path}?token=${encodeURIComponent(token)}`;
  return fetch(url,body?{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify({...body,token})}:{headers:{'Accept':'application/json'}})
    .then(r=>readApiResponse(r,`Solicitud ${path}`));
}function note(text){const t=$('toast');t.textContent=text;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),3200)}
function fillGrades(id,chosen){$(id).innerHTML=levels.map(l=>`<option value="${l.id}" ${l.id===chosen?'selected':''}>${h(l.label)}</option>`).join('')}
function setAuthMode(mode){const reg=mode==='register';$('authForm').dataset.mode=mode;$('displayNameWrap').classList.toggle('hidden',!reg);$('gradeWrap').classList.toggle('hidden',!reg);$('accountTypeWrap').classList.toggle('hidden',!reg);$('teacherRequestNote').classList.toggle('hidden',!reg||$('accountType').value!=='teacher');$('displayName').required=reg;$('registerGrade').required=reg;$('password').autocomplete=reg?'new-password':'current-password';$('authTitle').textContent=reg?'Crea tu cuenta educativa':'Bienvenido a EduPlay';$('authDescription').textContent=reg?'Regístrate para acceder a los contenidos y guardar tu avance.':'Ingresa a tu espacio de aprendizaje.';$('authSubmit').textContent=reg?'Crear cuenta':'Iniciar sesión';$('authError').classList.add('hidden');document.querySelectorAll('[data-auth-mode]').forEach(b=>b.classList.toggle('active',b.dataset.authMode===mode))}
async function auth(e){
  e.preventDefault();
  $('authError').classList.add('hidden');
  const reg=$('authForm').dataset.mode==='register';
  const body={username:$('username').value,password:$('password').value};
  if(reg){body.name=$('displayName').value;body.gradeId=$('registerGrade').value;body.accountType=$('accountType').value}
  try{
    const response=await fetch(reg?'/api/register':'/api/login',{
      method:'POST',
      headers:{'Content-Type':'application/json','Accept':'application/json'},
      body:JSON.stringify(body)
    });
    const d=await readApiResponse(response,reg?'Registro':'Inicio de sesión');
    if(!d.token||!d.user)throw Error('La API respondió, pero faltan los datos de sesión esperados.');
    token=d.token;
    localStorage.setItem('eduplayToken',token);
    $('password').value='';
    startApp(d.user);
    if(d.notice)note(d.notice);
  }catch(e){
    $('authError').textContent=e instanceof TypeError
      ?'No se pudo conectar con el servidor de EduPlay. En Vercel, comprueba que la API /api/login o /api/register esté desplegada; el servidor Python local no se ejecuta automáticamente allí.'
      :e.message;
    $('authError').classList.remove('hidden');
  }
}
async function restore(){token=localStorage.getItem('eduplayToken')||'';if(!token)return;try{const d=await api('/api/state');startApp(d.user)}catch{localStorage.removeItem('eduplayToken');token=''}}
async function showSetupHint(){
  try{
    const r=await fetch('/api/setup-status',{headers:{'Accept':'application/json'}});
    const d=await readApiResponse(r,'Comprobación inicial');
    if(!d.hasAccounts){$('setupHint').textContent='Primera vez: selecciona “Crear cuenta”. La primera cuenta será administración y podrá autorizar las cuentas de profesores.';$('setupHint').classList.remove('hidden')}
  }catch{
    $('setupHint').textContent='El servidor de autenticación no está respondiendo como API JSON. En uso local, inicia Iniciar-EduPlay.bat. En Vercel, debes desplegar también el backend y conectar una base de datos compatible.';
    $('setupHint').classList.remove('hidden')
  }
}function startApp(user){currentUser=user;$('authView').classList.add('hidden');$('appShell').classList.remove('hidden');$('accountName').textContent=user.name||user.username;$('roleTag').textContent=roleLabels[user.role]||'Cuenta';fillGrades('levelFilter',user.gradeId||'1');fillGrades('profileGrade',user.gradeId||'1');fillGrades('registerGrade','1');$('profileName').value=user.name||'';$('adminPanel').classList.toggle('hidden',user.role!=='admin');document.querySelectorAll('.teacher-tool').forEach(el=>el.classList.toggle('hidden',!['teacher','admin'].includes(user.role)));renderLearn();renderHome();renderClasses();renderProfile();setView('home')}
function setView(v){document.querySelectorAll('.app-view').forEach(el=>el.classList.add('hidden'));$(`${v}View`).classList.remove('hidden');document.querySelectorAll('.side-link').forEach(b=>b.classList.toggle('active',b.dataset.view===v));$('crumbView').textContent={home:'INICIO',learn:'APRENDER',classes:'MIS CLASES',profile:'PERFIL'}[v];$('heroTitle').textContent={home:'Aprendizaje con propósito.',learn:'Explora tu ruta de aprendizaje.',classes:'Aprender también es compartir.',profile:'Tu espacio educativo.'}[v];$('heroText').textContent={home:'Recursos, actividades y seguimiento organizados por grado.',learn:'Contenidos, ejemplos y actividades pensados para avanzar paso a paso.',classes:'Clases, tareas y acompañamiento de tus profesores.',profile:'Consulta tu información, tus resultados y los temas que vas dominando.'}[v];if(v==='classes')renderClasses();if(v==='profile')renderProfile()}
function getSelectedGrade(){return level($('levelFilter').value)}function subjectLabel(s,l=getSelectedGrade()){return subjects[s]?.label||s}function subjectKeyFromLabel(label){if(['Comunicación','Comunicación y Literatura','Lengua y Literatura'].includes(label))return 'Lenguaje';return Object.keys(subjects).find(key=>subjects[key].label===label)||label}
function makeTopics(s,grade){return gradeTopics[grade.id][s].map((title,i)=>({title,index:i,id:`${grade.id}|${s}|${i}`,unit:subjects[s].blocks[Math.min(4,Math.floor(i/2))],subject:s,grade}))}
function renderLearn(){const grade=getSelectedGrade();$('stageMeta').textContent=`${grade.stage} · ${grade.band}`;$('subjectGrid').innerHTML=Object.keys(subjects).map(s=>`<button class="subject-card ${subjects[s].color} ${selectedSubject===s?'selected':''}" data-subject="${s}"><span class="subject-symbol">${subjects[s].icon}</span><span class="subject-card-copy"><b>${h(subjectLabel(s,grade))}</b><small>10 temas · 5 unidades</small><em>${h(subjects[s].desc)}</em></span><span class="subject-arrow">↗</span></button>`).join('');document.querySelectorAll('[data-subject]').forEach(b=>b.onclick=()=>{selectedSubject=b.dataset.subject;renderLearn()});$('catalogTitle').textContent=subjectLabel(selectedSubject,grade);const q=$('searchInput').value.trim().toLocaleLowerCase('es');const topics=makeTopics(selectedSubject,grade).filter(t=>`${t.title} ${t.unit}`.toLocaleLowerCase('es').includes(q));$('unitGroups').innerHTML=subjects[selectedSubject].blocks.map((u,idx)=>{const ts=topics.filter(t=>t.unit===u);if(!ts.length)return '';return `<section class="unit-group"><div class="unit-heading"><span>UNIDAD ${String(idx+1).padStart(2,'0')}</span><h3>${h(u)}</h3><small>${ts.length} temas</small></div><div class="topic-grid">${ts.map(t=>`<button class="topic-card" data-topic="${h(t.id)}"><span class="topic-number">${String(t.index+1).padStart(2,'0')}</span><span><b>${h(t.title)}</b><small>${h(t.grade.label)} · Abrir lección interactiva →</small></span></button>`).join('')}</div></section>`}).join('')||'<p class="empty-state">No hay temas para esa búsqueda.</p>';document.querySelectorAll('[data-topic]').forEach(b=>b.onclick=()=>openLesson(makeTopics(selectedSubject,grade).find(t=>t.id===b.dataset.topic)))}
function lessonParts(t){const subject=t.subject,grade=Number(t.grade.id)||10,primary=grade<=3,topic=t.title.toLowerCase();let prereq,goal,explanation,example,activity,materials,question;if(subject==='Matemáticas'){prereq=grade<=3?'Conteo, comparación y representación con objetos':grade<=6?'Operaciones básicas, estimación y lectura de problemas':grade<=9?'Números racionales, álgebra y lectura de datos':'Álgebra, funciones, proporciones y análisis de datos';goal=`Interpretar ${topic} y aplicar una estrategia para resolver una situación cercana al estudiante.`;explanation=`Presenta una situación concreta relacionada con ${topic}. Modela cómo reconocer los datos, elegir una representación, resolver paso a paso y comprobar si el resultado tiene sentido. Permite comparar estrategias y explicar el razonamiento.`;example='Modela un problema de la comunidad con cantidades adecuadas al grado. Representa los datos con dibujos, objetos, tabla o expresión matemática y verifica el resultado por una segunda vía.';activity='En parejas, inventen un problema del hogar, la escuela o la comunidad. Resuélvanlo con dos representaciones y expliquen cuál les ayudó más.';materials='Cuaderno, pizarra, objetos para contar o medir; calculadora u hoja de cálculo como apoyo cuando corresponda.';question='¿Qué datos necesitas, qué estrategia elegirías y cómo comprobarías que la respuesta es razonable?'}else if(subject==='Lenguaje'){prereq=grade<=3?'Conversación, vocabulario, escucha y lectura de palabras o frases':grade<=6?'Comprensión de textos breves y escritura de párrafos':grade<=9?'Lectura crítica, organización de ideas y fuentes': 'Análisis textual, escritura académica y uso responsable de fuentes';goal=`Comprender y utilizar ${topic} para comunicar ideas con claridad, propósito y atención a la audiencia.`;explanation=`Parte de un texto o situación comunicativa vinculada con ${topic}. El docente modela cómo observar sus características, reconocer propósito y audiencia, y encontrar evidencias. El estudiante analiza, produce una respuesta propia y la revisa con criterios claros.`;example='Lee un texto breve apropiado al grado. Identifica una característica del tema, señala una evidencia concreta y explica con sus propias palabras lo que comprendió.';activity='En equipo, preparen una producción breve: planifiquen, elaboren un borrador, revísenlo con una lista de cotejo y presenten una versión mejorada.';materials='Textos breves adecuados al nivel, cuaderno, pizarra, diccionario y lista de cotejo; alternativa impresa si no hay conexión.';question='¿Qué evidencia respalda tu respuesta y cómo la explicarías con tus propias palabras?'}else if(subject==='Programación'){prereq=grade<=3?'Seguir instrucciones, reconocer patrones y explicar una secuencia':grade<=6?'Descomponer tareas y usar secuencias, eventos y decisiones':grade<=9?'Pseudocódigo, variables, condiciones y ciclos básicos':'Algoritmos, estructuras de datos y diseño modular';goal=`Aplicar ${topic} para diseñar una solución de software comprensible, comprobable y útil para una necesidad real.`;explanation=grade<=3?`Representa ${topic} con tarjetas, dibujos o bloques visuales. Una computadora sigue instrucciones precisas: el grupo ordena pasos, detecta ambigüedades y prueba la secuencia como si fuera el programa.`:grade<=6?`Conecta ${topic} con un programa por bloques o pseudocódigo. El docente modela entrada, proceso y resultado; el grupo construye una solución pequeña, la prueba con ejemplos y corrige instrucciones.`:`Conecta ${topic} con el ciclo de desarrollo: comprender al usuario, diseñar algoritmo e interfaz, implementar una versión pequeña, probar casos y documentar mejoras. Puede trabajarse con bloques, pseudocódigo o el lenguaje disponible en el centro.`;example=grade<=3?'Ejemplo: para que un personaje llegue a una estrella, escribe AVANZAR, AVANZAR, GIRAR. Simula cada orden y corrige el paso que no conduce al objetivo.':grade<=6?'Ejemplo: crea un algoritmo que lea dos cantidades, las sume y muestre el resultado. Prueba con 3 y 4; luego prueba con 0 y explica qué debe ocurrir.':'Ejemplo: diseña una función que recibe datos, valida que sean correctos y devuelve un resultado. Define un caso normal, uno vacío y uno límite antes de considerarla lista.';activity='Reto de desarrollo: elijan una necesidad escolar, describan quién usaría la solución, diseñen el algoritmo o flujo de pantallas, construyan un prototipo en papel/bloques/código y prueben al menos tres casos. Registren un error encontrado y la mejora aplicada.';materials=grade<=3?'Tarjetas con comandos, flechas, papel cuadriculado y bloques visuales impresos; no requiere computadora.':grade<=6?'Pseudocódigo, tarjetas o entorno de bloques disponible; cuaderno para registrar entradas, resultados y errores.':'Computadora opcional con editor o entorno aprobado por el centro; también se puede prototipar en papel. Usar datos ficticios y proteger contraseñas.';question='¿Cuál es la entrada, qué pasos transforman los datos y qué pruebas demostrarían que tu programa funciona?'}else{prereq=grade<=3?'Observar movimientos, seguir rutas y construir con piezas o materiales seguros':grade<=6?'Reconocer estructuras, mecanismos simples y secuencias de control':grade<=9?'Usar condiciones, sensores, mediciones y criterios de diseño':'Integrar mecánica, electrónica, programación y pruebas de sistemas';goal=`Explorar ${topic} dentro de un prototipo que responda a una necesidad, con criterios de éxito y pruebas observables.`;explanation=grade<=3?`Explora ${topic} con un robot humano, una maqueta o un dibujo. Relaciona cada instrucción con un movimiento y observa qué cambia al modificar una orden. La idea es diseñar, probar y explicar; no se necesita un kit electrónico.`:grade<=6?`Investiga ${topic} con una maqueta o simulador. Distingue estructura, mecanismo, entrada y respuesta; construye una versión simple y cambia una variable a la vez para entender su efecto.`:`Integra ${topic} en un ciclo de ingeniería: define requisitos y usuario, dibuja el sistema, identifica entradas y salidas, implementa una solución, mide resultados y documenta iteraciones. Un kit o simulador es opcional.`;example='Ejemplo: plantea una ruta con salida y meta. El robot recibe una secuencia de órdenes; si no llega, registra dónde se desvió, identifica la instrucción causante y modifica solo ese paso.';activity='Reto robótico: diseñen un prototipo o simulación para resolver una necesidad del aula. Dibujen componentes, indiquen sensores/entradas y actuadores/salidas, establezcan tres criterios medibles, hagan pruebas y propongan una mejora.';materials=grade<=3?'Flechas y cuadrícula de papel, cajas pequeñas o robot humano; materiales reutilizables, sin electricidad.':grade<=6?'Cartón, ruedas y ejes de maqueta, tarjetas de sensores/actuadores o simulador; kit real opcional.':'Kit de bajo voltaje o simulador, fichas técnicas y bitácora. Revisar conexiones y trabajar con supervisión docente; evitar conexión a la red eléctrica.';question='¿Qué señal recibe el prototipo, qué respuesta produce y cómo medirías si cumple su objetivo?'}return{prereq,goal,explanation,example,activity,materials,question}}function interactiveMarkup(t){if(t.subject==='Programación')return `<div class="interactive-lab code-lab"><div class="lab-heading"><span>LABORATORIO DE CÓDIGO</span><b>Predice el resultado</b></div><pre><code>total = 0
repetir para n desde 1 hasta 3:
  total = total + n
mostrar(total)</code></pre><p>¿Qué valor mostrará el algoritmo al finalizar?</p><div class="lab-options"><button data-answer="3">3</button><button data-answer="5">5</button><button data-answer="6">6</button><button data-answer="9">9</button></div><div class="lab-result" id="labResult" aria-live="polite">Sigue el valor de <b>total</b> en cada repetición.</div></div>`;if(t.subject==='Robótica')return `<div class="interactive-lab robot-lab"><div class="lab-heading"><span>SIMULADOR ROBÓTICO</span><b>Misión: llega a la estación</b></div><p>Programa la ruta con las flechas. El robot inicia abajo a la izquierda; la meta está arriba a la derecha.</p><div id="robotGrid" class="robot-grid">${Array.from({length:16},(_,i)=>`<div class="robot-cell ${i===12?'robot-at':''} ${i===3?'robot-goal':''}" data-cell="${i}">${i===12?'🤖':i===3?'◆':''}</div>`).join('')}</div><div class="robot-controls"><button data-move="up" aria-label="Mover arriba">↑</button><button data-move="left" aria-label="Mover izquierda">←</button><button data-move="down" aria-label="Mover abajo">↓</button><button data-move="right" aria-label="Mover derecha">→</button><button data-reset-robot="1">Reiniciar ruta</button></div><div class="lab-result" id="labResult" aria-live="polite">Cada orden es una instrucción. Planea una secuencia y prueba.</div></div>`;if(t.subject==='Matemáticas')return `<div class="interactive-lab math-lab"><div class="lab-heading"><span>RETO RÁPIDO</span><b>Calcula y comprueba</b></div><p>Una caja tiene 8 filas con 7 semillas cada una. ¿Cuántas semillas hay?</p><div class="lab-options"><button data-answer="54">54</button><button data-answer="56">56</button><button data-answer="64">64</button></div><div class="lab-result" id="labResult" aria-live="polite">Puedes dibujar filas iguales o usar una multiplicación.</div></div>`;return `<div class="interactive-lab language-lab"><div class="lab-heading"><span>RETO DE LECTURA</span><b>Encuentra la evidencia</b></div><p>Lee: “El huerto escolar produjo más tomates este año porque el grupo instaló riego por goteo”. ¿Qué parte explica la causa?</p><div class="lab-options"><button data-answer="riego">Instalaron riego por goteo</button><button data-answer="huerto">El huerto es escolar</button><button data-answer="tomates">Hay tomates</button></div><div class="lab-result" id="labResult" aria-live="polite">Elige la frase que explica por qué ocurrió el resultado.</div></div>`}
function wireInteractive(t){const result=$('labResult');document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{const correct=t.subject==='Programación'?b.dataset.answer==='6':t.subject==='Matemáticas'?b.dataset.answer==='56':b.dataset.answer==='riego';result.className=`lab-result ${correct?'success':'try-again'}`;result.textContent=correct?(t.subject==='Programación'?'¡Correcto! 1 + 2 + 3 = 6. Has seguido el cambio de la variable.':t.subject==='Matemáticas'?'¡Correcto! 8 × 7 = 56. Representaste grupos iguales.':'¡Correcto! El riego por goteo es la evidencia que explica la causa.'): 'Aún no. Vuelve a revisar los datos y prueba otra respuesta.';const answer=$('practiceAnswer');if(correct&&answer)answer.value=`Reto interactivo resuelto: ${result.textContent}`});let pos=12,steps=0;const draw=()=>document.querySelectorAll('[data-cell]').forEach(c=>{const i=Number(c.dataset.cell);c.classList.toggle('robot-at',i===pos);c.textContent=i===pos?'🤖':i===3?'◆':''});document.querySelectorAll('[data-move]').forEach(b=>b.onclick=()=>{const r=Math.floor(pos/4),c=pos%4,m=b.dataset.move;const nr=r+(m==='down'?1:m==='up'?-1:0),nc=c+(m==='right'?1:m==='left'?-1:0);if(nr<0||nr>3||nc<0||nc>3){result.className='lab-result try-again';result.textContent='El robot no puede salir de la cuadrícula. Cambia la secuencia.';return}pos=nr*4+nc;steps++;draw();if(pos===3){result.className='lab-result success';result.textContent=`¡Misión cumplida en ${steps} instrucciones! Ya puedes explicar la secuencia que diseñaste.`;const answer=$('practiceAnswer');if(answer)answer.value=`Simulación robótica completada en ${steps} instrucciones. Mi ruta fue planificada y probada.`}else{result.className='lab-result';result.textContent=`Paso ${steps}: el robot avanzó. Observa su posición y decide la siguiente instrucción.`}});document.querySelector('[data-reset-robot]')?.addEventListener('click',()=>{pos=12;steps=0;draw();result.className='lab-result';result.textContent='Ruta reiniciada. Planifica otra secuencia.'})}
function openLesson(t){if(!t)return;const d=lessonParts(t);$('lessonContent').innerHTML=`<div class="eyebrow">${h(subjectLabel(t.subject,t.grade).toUpperCase())} · ${h(t.grade.label.toUpperCase())} · ${h(t.unit.toUpperCase())}</div><h2>${h(t.title)}</h2><p class="view-subtitle"><b>Propósito:</b> ${h(d.goal)}</p><div class="lesson-section"><h3>Antes de comenzar</h3><p><b>Requisitos previos:</b> ${h(d.prereq)}</p></div><div class="lesson-section"><h3>Explicación para la clase</h3><p>${h(d.explanation)}</p></div><div class="lesson-section"><h3>Ejemplo guiado</h3><p>${h(d.example)}</p></div><div class="lesson-section"><h3>Materiales</h3><p>${h(d.materials)}</p></div><div class="lesson-section"><h3>Actividad de aprendizaje</h3><p>${h(d.activity)}</p></div>${interactiveMarkup(t)}<div class="lesson-section"><h3>Pregunta para pensar</h3><p>${h(d.question)}</p></div>${currentUser.role==='student'?`<form id="practiceForm" class="record-form"><label>Explica lo aprendido<textarea id="practiceAnswer" required minlength="2" rows="4" placeholder="Escribe tu razonamiento o lo que descubriste en el reto"></textarea></label><label>Autoevaluación<select id="practiceCheck"><option>Necesito más práctica</option><option>Voy comprendiendo</option><option>Lo puedo explicar</option></select></label><button class="primary-button">Guardar práctica</button></form>`:`<div class="teacher-tip"><b>Orientación docente:</b> realiza primero el reto con el grupo, solicita que expliquen sus decisiones y recoge evidencias para guiar la siguiente actividad. Adapta tiempos y recursos al nivel del curso.</div>`}`;$('lessonDialog').showModal();wireInteractive(t);$('practiceForm')?.addEventListener('submit',async e=>{e.preventDefault();try{await api('/api/practice',{gradeId:t.grade.id,subject:subjectLabel(t.subject,t.grade),topicId:t.id,topicTitle:t.title,answer:$('practiceAnswer').value,selfCheck:$('practiceCheck').value});note('Práctica guardada en tu progreso.');$('lessonDialog').close();renderProfile()}catch(err){note(err.message)}})}function renderHome(){const g=level(currentUser.gradeId||'1');$('dashboard').innerHTML=`<article class="dashboard-card"><span>MI NIVEL</span><b>${h(g.label)}</b><small>${h(g.band)}</small></article><article class="dashboard-card"><span>MI ROL</span><b>${roleLabels[currentUser.role]}</b><small>${currentUser.role==='student'?'Explora y registra tus prácticas':'Acompaña y organiza el aprendizaje'}</small></article><article class="dashboard-card"><span>RUTAS</span><b>6 materias</b><small>Matemáticas · Lenguaje · Ciencias · Sociales · Software · Robótica</small></article>`;$('homeTopics').innerHTML=Object.keys(subjects).map(s=>{const t=makeTopics(s,g)[0];return `<button class="topic-card home-subject-card ${subjects[s].color}" data-home-topic="${h(s)}"><span class="topic-number">${subjects[s].icon}</span><span><b>${h(subjectLabel(s,g))}</b><small>${h(t.title)} · ${h(g.label)} · Explorar →</small></span></button>`}).join('');document.querySelectorAll('[data-home-topic]').forEach(b=>b.onclick=()=>{selectedSubject=b.dataset.homeTopic;$('levelFilter').value=currentUser.gradeId||'1';renderLearn();setView('learn');openLesson(makeTopics(selectedSubject,level(currentUser.gradeId||'1'))[0])})}async function renderClasses(){const teacher=['teacher','admin'].includes(currentUser.role);$('classesHeading').textContent=teacher?'Clases y tareas':'Mis clases';$('classesIntro').textContent=teacher?'Crea grupos, comparte el código de acceso, asigna actividades y revisa entregas.':'Únete con el código de tu profesor para consultar tareas y entregar actividades.';$('classActions').innerHTML=teacher?`<form id="createClass" class="inline-form"><h3>Crear una clase</h3><label>Nombre del grupo<input name="name" required maxlength="80" placeholder="Ej. Matemáticas 7.º A"></label><label>Grado<select name="gradeId">${levels.map(l=>`<option value="${l.id}">${h(l.label)}</option>`)}</select></label><label>Sección<input name="section" maxlength="24" placeholder="A"></label><button class="primary-button">Crear clase</button></form>`:`<form id="joinClass" class="inline-form"><h3>Unirme a una clase</h3><label>Código de clase<input name="joinCode" required maxlength="12" placeholder="Código del profesor"></label><button class="primary-button">Unirme</button></form>`;$('createClass')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target);try{const d=await api('/api/classes',{name:f.get('name'),gradeId:f.get('gradeId'),section:f.get('section')});note(`Clase creada. Código: ${d.class.joinCode}`);await renderClasses()}catch(err){note(err.message)}});$('joinClass')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target);try{await api('/api/classes/join',{joinCode:f.get('joinCode')});note('Ya formas parte de la clase.');await renderClasses()}catch(err){note(err.message)}});try{const d=await api('/api/classes');classCache=d.classes;$('classList').innerHTML=d.classes.length?d.classes.map(c=>`<button class="class-card ${selectedClassId===c.id?'selected':''}" data-class="${h(c.id)}"><b>${h(c.name)}</b><small>${h(level(c.grade_id).label)} · ${teacher?`${c.member_count} estudiantes · ${c.assignment_count} tareas`:`Profesor/a: ${h(c.teacher_name||'Docente')} · ${c.assignment_count} tareas`}</small>${teacher?`<span>Código: ${h(c.join_code)}</span>`:''}</button>`).join(''):'<div class="empty-state">Todavía no hay clases. Crea una o solicita el código de acceso a tu profesor.</div>';document.querySelectorAll('[data-class]').forEach(b=>b.onclick=()=>{selectedClassId=b.dataset.class;renderClassDetail(b.dataset.class)});if(selectedClassId)renderClassDetail(selectedClassId)}catch(err){$('classList').innerHTML=`<p class="empty-state">${h(err.message)}</p>`}}
function renderHome(){const g=level(currentUser.gradeId||'1');$('dashboard').innerHTML=`<article class="dashboard-card"><span>MI NIVEL</span><b>${h(g.label)}</b><small>${h(g.band)}</small></article><article class="dashboard-card"><span>MI ROL</span><b>${roleLabels[currentUser.role]}</b><small>${currentUser.role==='student'?'Explora y registra tus prácticas':'Acompaña y organiza el aprendizaje'}</small></article><article class="dashboard-card"><span>RUTAS</span><b>6 materias</b><small>Matemáticas · Lenguaje · Ciencias · Sociales · Software · Robótica</small></article>`;$('homeTopics').innerHTML=Object.keys(subjects).map(s=>{const t=makeTopics(s,g)[0];return `<button class="topic-card home-subject-card ${subjects[s].color}" data-home-topic="${h(s)}"><span class="topic-number">${subjects[s].icon}</span><span><b>${h(subjectLabel(s,g))}</b><small>${h(t.title)} · ${h(g.label)} · Explorar →</small></span></button>`}).join('');document.querySelectorAll('[data-home-topic]').forEach(b=>b.onclick=()=>{selectedSubject=b.dataset.homeTopic;$('levelFilter').value=currentUser.gradeId||'1';renderLearn();setView('learn');openLesson(makeTopics(selectedSubject,level(currentUser.gradeId||'1'))[0])})}
